mapper.sql:
where true
  and o.order_date >= #{q.from}
  and o.order_date <= #{q.to}
  and o.cust_id = #{q.custId}
  and o.status = #{q.status}

  and (o.order_no like '%' || #{q.keyword} || '%' escape '\' or o.cust_po_no ilike '%' || #{q.keyword} || '%' escape '\')


  and exists (select 1 from sal_order_line l where l.order_id = o.order_id and l.item_id = #{q.itemId})


  and exists (select 1 from sal_order_line l where l.order_id = o.order_id )

and l.status = 'OPEN'
and l.due_date >= #{q.dueFrom}
and l.due_date <= #{q.dueTo}

mapper.select:
select 
  from sal_order o join mst_cust c on c.cust_id = o.cust_id
 where o.order_id = #{id}

mapper.update:
update sal_order
   set cust_po_no = #{f.custPoNo}, order_date = #{f.orderDate}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where order_id = #{id} and row_ver = #{rowVer}

mapper.select:
select 
  from sal_order_line l join mst_item i on i.item_id = l.item_id
 where l.line_id = #{id}

select 
  from sal_order_line l join mst_item i on i.item_id = l.item_id
 where l.order_id = #{orderId} and l.line_no = #{lineNo}

mapper.update:
update sal_order_line
   set status = #{status}, cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where line_id = #{id} and status = 'OPEN' and row_ver = #{rowVer}

update sal_order_line
   set status = 'CANCELLED', cancel_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where order_id = #{orderId} and status = 'OPEN'
